PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,display_name TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,expires_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS subjects (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS topics (id TEXT PRIMARY KEY,subject_id TEXT NOT NULL,name TEXT NOT NULL,completed INTEGER NOT NULL DEFAULT 0,position INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS notes (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,subject_id TEXT,topic_id TEXT,title TEXT NOT NULL,content TEXT NOT NULL,tags_json TEXT NOT NULL DEFAULT '[]',pinned INTEGER NOT NULL DEFAULT 0,archived INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL,FOREIGN KEY(topic_id) REFERENCES topics(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS flashcards (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,subject_id TEXT,topic_id TEXT,front TEXT NOT NULL,back TEXT NOT NULL,interval INTEGER NOT NULL DEFAULT 1,ease REAL NOT NULL DEFAULT 2.5,due_at TEXT NOT NULL,reviews INTEGER NOT NULL DEFAULT 0,state TEXT NOT NULL DEFAULT 'new',created_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL,FOREIGN KEY(topic_id) REFERENCES topics(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS flashcard_reviews (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,flashcard_id TEXT NOT NULL,rating TEXT NOT NULL,interval INTEGER NOT NULL,state TEXT NOT NULL,reviewed_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(flashcard_id) REFERENCES flashcards(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS quizzes (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,subject_id TEXT,topic_id TEXT,title TEXT NOT NULL,difficulty TEXT NOT NULL,questions_json TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL,FOREIGN KEY(topic_id) REFERENCES topics(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS quiz_attempts (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,quiz_id TEXT,title TEXT NOT NULL,score INTEGER NOT NULL,total INTEGER NOT NULL,percent INTEGER NOT NULL,completed_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(quiz_id) REFERENCES quizzes(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS study_sessions (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,subject_id TEXT,topic_id TEXT,activity TEXT NOT NULL,minutes INTEGER NOT NULL,started_at TEXT NOT NULL,ended_at TEXT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL,FOREIGN KEY(topic_id) REFERENCES topics(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS study_goals (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,minutes INTEGER NOT NULL DEFAULT 25,updated_at TEXT NOT NULL,UNIQUE(user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS ai_conversations (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,title TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS ai_messages (id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL,role TEXT NOT NULL,content TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(conversation_id) REFERENCES ai_conversations(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,type TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,read INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS achievements (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,code TEXT NOT NULL,unlocked_at TEXT NOT NULL,UNIQUE(user_id,code),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS user_progress (user_id TEXT PRIMARY KEY,xp INTEGER NOT NULL DEFAULT 0,level INTEGER NOT NULL DEFAULT 1,longest_streak INTEGER NOT NULL DEFAULT 0,last_reward_date TEXT,weekly_reward_date TEXT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS xp_transactions (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,amount INTEGER NOT NULL,source TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS notification_preferences (user_id TEXT PRIMARY KEY,daily_reminders INTEGER NOT NULL DEFAULT 1,streak_alerts INTEGER NOT NULL DEFAULT 1,achievement_alerts INTEGER NOT NULL DEFAULT 1,review_alerts INTEGER NOT NULL DEFAULT 1,goal_alerts INTEGER NOT NULL DEFAULT 1,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);CREATE INDEX IF NOT EXISTS idx_notes_user ON notes(user_id);CREATE INDEX IF NOT EXISTS idx_cards_due ON flashcards(user_id,due_at);CREATE INDEX IF NOT EXISTS idx_card_reviews_user ON flashcard_reviews(user_id,reviewed_at);CREATE INDEX IF NOT EXISTS idx_messages_conversation ON ai_messages(conversation_id);CREATE INDEX IF NOT EXISTS idx_study_sessions_user_started ON study_sessions(user_id,started_at);CREATE INDEX IF NOT EXISTS idx_xp_transactions_user_created ON xp_transactions(user_id,created_at);CREATE INDEX IF NOT EXISTS idx_notifications_user_created ON notifications(user_id,created_at);CREATE INDEX IF NOT EXISTS idx_quiz_attempts_user_completed ON quiz_attempts(user_id,completed_at);
